// Work out how many shots are needed and ask Claude to plan them.
const f = $input.first().json;
const SYSTEM = "You are a film director preparing prompts for an AI text-to-video model that can only generate a few seconds at a time. Break the user's idea into exactly the requested number of consecutive shots that together tell the whole idea in order.\n\n- `character`: one precise, reusable description of every recurring subject (age, clothing, colours, hair, props). It is pasted into every shot prompt so the subject looks identical in each clip - be specific.\n- `look`: one reusable description of setting, lighting, colour palette, lens and style (e.g. \"photorealistic, warm golden-hour light, shallow depth of field, 35mm\").\n- Each shot: `action` is what visibly happens in that clip, written so it can be filmed in the given number of seconds (one or two simple actions, no time jumps). `camera` is the camera movement.\n- In continuous mode every shot must pick up exactly where the previous one ended (same place, same moment, no cuts). In shots mode each shot may reframe but should still flow naturally.\n- Do not write on-screen text, captions, logos or dialogue unless the user asks for them.\n- `title`: a short title.";
const SCHEMA = {
  "type": "object",
  "additionalProperties": false,
  "required": [
    "title",
    "character",
    "look",
    "shots"
  ],
  "properties": {
    "title": {
      "type": "string"
    },
    "character": {
      "type": "string"
    },
    "look": {
      "type": "string"
    },
    "shots": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "action",
          "camera"
        ],
        "properties": {
          "action": {
            "type": "string"
          },
          "camera": {
            "type": "string"
          }
        }
      }
    }
  }
};

const seconds = parseInt(String(f.seconds || '40'), 10);
const aspect = String(f.format || '16:9').split(' ')[0];
const provider = f.provider || 'auto';
// "Continuous" needs Veo's extend feature; fal.ai always uses separate shots.
const mode = provider === 'fal' || String(f.style || '').startsWith('Separate') ? 'shots' : 'extend';
const shots = mode === 'extend'
  ? 1 + Math.max(0, Math.ceil((seconds - 8) / 7))       // 8 s clip + 7 s extensions
  : Math.max(1, Math.ceil((seconds - 0.6) / (8 - 0.6)));  // 8 s clips joined with crossfades

const modeText = mode === 'extend'
  ? 'continuous mode (one uninterrupted take, no cuts)'
  : 'shots mode (separate clips joined with short crossfades)';
const content = `Number of shots: ${shots}\nSeconds per shot: about 8\nMode: ${modeText}\n\n<idea>\n${String(f.idea || '').trim()}\n</idea>`;

return [{
  json: {
    job: { idea: f.idea, seconds, aspect, provider, mode, music_url: f.music_url || '' },
    request: {
      model: 'claude-opus-5-5',
      max_tokens: 16000,
      system: SYSTEM,
      messages: [{ role: 'user', content }],
      output_config: { effort: 'medium', format: { type: 'json_schema', schema: SCHEMA } },
      fallbacks: 'default',
    },
  },
}];

// Check Claude's shot plan and build the video job.
const res = $input.first().json;
const job = $('Build Claude Request').first().json.job;

if (res.stop_reason === 'refusal') throw new Error('Claude declined to plan this video.');
if (res.stop_reason === 'max_tokens') throw new Error('The shot plan was cut off - try a shorter idea.');
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const plan = JSON.parse(text);
if (!Array.isArray(plan.shots) || plan.shots.length === 0) throw new Error('Claude returned no shots.');

const body = { ...job, plan };
if (!body.music_url) delete body.music_url;
return [{ json: body }];
